            assert obligations[identity] == int(Decimal(str(row['Obligation (EUR)'])) * 100)
    snapshot = json.loads((run / f'batches/{batch}.json').read_text())
    assert set(obligations) == {row['request_id'] for row in snapshot['requests']}
    for row in snapshot['requests']:
        assert row['amount_cents'] == obligations[row['request_id']]
        assert (row['claim_id'], row['payee'], row['currency']) == original_bindings[row['request_id']]
    result['native_money_against_snapshots'][batch-1]['current_obligation_cents'] = sum(obligations.values())
    result['native_money_against_snapshots'][batch-1]['all_original_request_bindings_and_current_obligations_agree'] = True
output.write_text(json.dumps(result, indent=2)+'\n')
print(output)
print('All four batches: every request binding and obligation agrees directly with native Finance history.')
